+
+ override fun startFeedback() {
+ ringPlayer.playRing()
+ if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
+ vibrationPlayer.startVibration()
+ }
+ }
+
+ override fun stopFeedback() {
+ ringPlayer.stopRing()
